sys_variable_value.value:
(function execute(inputs, outputs) {
    
    var P = 'x_2078844_gstin_0.';
    var maxAttempts = (parseInt(gs.getProperty(P + 'gstin.retry.count', '3'), 10) || 3) + 1;
    var attempt = parseInt(inputs.attempt, 10) || 1;
    var pid = (inputs.profile && inputs.profile.getUniqueValue) ? inputs.profile.getUniqueValue() : String(inputs.profile);

    var r = new x_2078844_gstin_0.GSTVerifier().verify(pid, String(inputs.trigger),
        { attempt: attempt, lastAttempt: (attempt >= maxAttempts) });

    outputs.result        = r.result;
    outputs.reason        = r.reason;
    outputs.category      = r.category;
    outputs.retry         = (r.retryable === true && attempt < maxAttempts);
    outputs.next_attempt  = attempt + 1;
    outputs.delay_seconds = parseInt(gs.getProperty(P + 'gstin.retry.delay.seconds', '60'), 10) || 60;
})(inputs, outputs);

